import {MfeInitFunctionConfig} from '../interfaces';

export interface InitializeMfeConfig extends MfeInitFunctionConfig {
    /**
     * The Module Federation 'name'.
     */
    remote: string;

    /**
     * The Module Federation 'exposes'.
     */
    module: string;

    /**
     * The full URL to the MFE, usually ending in 'remoteEntry.js'.
     */
    url: string;
}
